import re

def anti_shuffle(s):
    # Split the string into tokens: words with attached punctuation and spaces
    tokens = re.findall(r'\S+|\s+', s)
    result = []
    for token in tokens:
        if token.isspace():
            # Keep spaces as is
            result.append(token)
        else:
            # Sort characters of the word (letters + attached punctuation)
            sorted_token = ''.join(sorted(token))
            result.append(sorted_token)
    return ''.join(result)

